-- 883 returned to production
-- These ask the same thing in fewer characters. They were already being served.
UPDATE public.questions AS q SET
    question_text = v.question_text,
    correct_answer = v.correct_answer,
    incorrect_answers = v.incorrect_answers,
    original_question_text = COALESCE(q.original_question_text, q.question_text),
    original_correct_answer = COALESCE(q.original_correct_answer, q.correct_answer),
    original_incorrect_answers = COALESCE(q.original_incorrect_answers, q.incorrect_answers),
    in_production = true,
    shorten_status = 'shortened',
    answer_shorten_status = 'shortened',
    quality_status = NULL,
    quality_issues = NULL,
    last_quality_check = now(),
    updated_at = now()
  FROM (VALUES
    ('5e1e4b2a-375b-4150-ad47-06f39fdf4d44'::uuid, '1980 Moscow Olympics: what Cold War event impacted participation?', 'The Afghan invasion', '["The Cuban embargo", "The Berlin Wall", "The Korean War"]'::jsonb),
