-- 641 held in the Library for review
-- These ask something different: the original could not be shortened without
-- losing its point, so it was replaced with a better question on the same subject.
UPDATE public.questions AS q SET
    question_text = v.question_text,
    correct_answer = v.correct_answer,
    incorrect_answers = v.incorrect_answers,
    original_question_text = COALESCE(q.original_question_text, q.question_text),
    original_correct_answer = COALESCE(q.original_correct_answer, q.correct_answer),
    original_incorrect_answers = COALESCE(q.original_incorrect_answers, q.incorrect_answers),
    in_production = false,
    shorten_status = 'pending_review',
    answer_shorten_status = 'pending_review',
    quality_status = NULL,
    quality_issues = NULL,
    last_quality_check = now(),
    updated_at = now()
  FROM (VALUES
